node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search all tables for 'EX001' or 'BostonTech'
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  for (const col of cols) {
    if (col.type === 'TEXT' || col.type === '') {
      try {
        const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE ' + col.name + ' LIKE ? OR ' + col.name + ' LIKE ?').all('%EX001%', '%BostonTech%');
        if (rows.length > 0) {
          console.log('Found in', t.name + '.' + col.name + ':', rows.length, 'rows');
          rows.forEach(r => console.log(JSON.stringify(r)));
        }
      } catch(e) {}
    }
  }
}
db.close();
"

