node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const flights = db.prepare(\"SELECT flight_id, origin, destination, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();

// Collect all unique dates
let allDates = new Set();
let sfoFlights = [];
let bosFlights = [];

for (const f of flights) {
  const dates = JSON.parse(f.dates_json || '{}');
  for (const d of Object.keys(dates)) {
    allDates.add(d);
  }
  if (f.origin === 'SFO') sfoFlights.push(f.flight_id + ' -> ' + f.destination);
  if (f.destination === 'BOS') bosFlights.push(f.flight_id + ' from ' + f.origin);
  if (f.origin === 'BOS') bosFlights.push(f.flight_id + ' BOS -> ' + f.destination);
}

const sortedDates = [...allDates].sort();
console.log('All available dates in DB:', sortedDates);
console.log();
console.log('SFO departures:', sfoFlights);
console.log();
console.log('BOS related:', bosFlights);
db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const flights = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();

// Get unique origin-destination pairs
let routes = new Set();
let origins = new Set();
let destinations = new Set();

for (const f of flights) {
  routes.add(f.origin + ' -> ' + f.destination);
  origins.add(f.origin);
  destinations.add(f.destination);
}

console.log('All unique origins:', [...origins].sort());
console.log('All unique destinations:', [...destinations].sort());
console.log();
console.log('All routes:');
[...routes].sort().forEach(r => console.log('  ' + r));

// Show all flights with their dates
console.log();
console.log('=== Full flight details ===');
for (const f of flights) {
  const dates = JSON.parse(f.dates_json || '{}');
  const availDates = Object.entries(dates).filter(([d, info]) => info.status === 'available').map(([d]) => d);
  console.log(f.flight_id + ': ' + f.origin + ' -> ' + f.destination + ' dep=' + f.departure_time + ' arr=' + f.arrival_time + ' dates=' + availDates.join(','));
}
db.close();
"
